import unicodedata
def token_jaccard(a, b):
    def toks(s):
        s = unicodedata.normalize('NFC', s)
        return set(s.casefold().split())
    A, B = toks(a), toks(b)
    if not A and not B:
        return 1.0
    if not A or not B:
        return 0.0
    return len(A & B) / len(A | B)
