import unicodedata
from typing import Any

def nfc(s: str) -> str:
    return unicodedata.normalize('NFC', s)

def normalize_nombre(raw: str) -> tuple[str, list[str]]:
    value = nfc(raw)
    value = ' '.join(value.split())
    return value, ['nfc', 'collapse_spaces']

def normalize_email(raw: str) -> tuple[str, list[str]]:
    value = raw.strip().casefold()
    transforms = ['strip', 'casefold']
    if value.count('@') != 1 or any(ch.isspace() for ch in value):
        raise ValueError('email requiere un @ y cero espacios')
    local, domain = value.split('@')
    if not local or not domain:
        raise ValueError('email requiere local y dominio')
    return value, transforms

def normalize_phone(raw: str) -> tuple[str, list[str]]:
    return ''.join(ch for ch in raw if ch.isdigit()), ['digits_only']

def normalize_record(raw: dict[str, Any]) -> dict[str, Any]:
    result = {'raw': dict(raw), 'normalized': {}, 'transforms': {}, 'status': 'ok', 'review': []}
    nombre, nt = normalize_nombre(str(raw.get('nombre', '')))
    result['normalized']['nombre'] = nombre
    result['transforms']['nombre'] = nt
    try:
        email, et = normalize_email(str(raw.get('email', '')))
        result['normalized']['email'] = email
        result['transforms']['email'] = et
    except ValueError as exc:
        result['normalized']['email'] = None
        result['transforms']['email'] = ['strip', 'casefold']
        result['status'] = 'review'
        result['review'].append(str(exc))
    phone, pt = normalize_phone(str(raw.get('telefono', '')))
    result['normalized']['telefono'] = phone
    result['transforms']['telefono'] = pt
    toks = nombre.split()
    if len(toks) < 3:
        result['status'] = 'review'
        result['review'].append('nombre con menos de tres tokens; no se inventan apellidos')
        result['normalized']['nombre_parse'] = {'given': nombre, 'ap1': None, 'ap2': None}
    else:
        result['normalized']['nombre_parse'] = {'given': ' '.join(toks[:-2]), 'ap1': toks[-2], 'ap2': toks[-1]}
    return result
